	}
	sources, err := DiscoverSources(resolved)
	if err != nil {
		return StudyListing{}, err
	}
	dimensions, err := DiscoverDimensions(resolved)
	if err != nil {
		return StudyListing{}, err
	}
	studyConfig, dimensionOrder, err := LoadStudyConfig(resolved, dimensions)
	if err != nil {
		return StudyListing{}, err
	}
	return StudyListing{
